#define smoothness 10
#define waveN 5.
struct wave {
float size;
float offset;
float frequency;
float speed;
float vertical;
};
int predict(wave a,vec2 pos) {
    return pos.y - a.vertical <= sin(pos.x/a.frequency+iTime/a.speed+a.offset)*a.size ? 1 : 0;
}
vec3 lerp(vec3 a,vec3 b,float t) {
    return a * (.1-t) + b * t;
}
int ocean(vec2 pos) {
    return predict(wave(25.,0.,50.,3.,0.),pos-vec2(0,50))+
    predict(wave(23.,0.,40.,1.,0.),pos-vec2(0,50))+
    predict(wave(20.,10.,45.,0.5,0.),pos-vec2(0,50))+
    predict(wave(30.,20.,100.,2.,10.),pos-vec2(0,50))+
    predict(wave(25.,20.,50.,1.5,5.),pos-vec2(0,50));
}
vec4 background(vec2 pos) {
    return vec4(lerp(normalize(vec3(255, 182, 60))*2.,normalize(vec3(255, 182, 60))*10.,pos.y/iResolution.y),0);
}
vec4 render(vec2 pos) {
    int current = ocean(pos);
    if (current == 0) {
        return background(pos);
    } else {
        return normalize(vec4(0,float(current)/(waveN + 1.),float(current)/waveN,0)*(float(current) + background(pos)));
    }
}
vec4 smoothP(vec2 pos) {
    int sampleN = 0;
    vec4 color = vec4(0);
    for (int y = -smoothness;y <= smoothness;y++) {
        for (int x = -smoothness;x <= smoothness;x++) {
            if ((x*x + y*y <= smoothness*smoothness && ocean(vec2(x,y) + pos) > 0) || (x*x + y*y <= 1 && ocean(vec2(x,y) + pos) < 2)) {
                sampleN++;
                color += render(pos + vec2(x,y));
            }
        }
    }
    return color / vec4(sampleN);
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = vec4(smoothP(fragCoord).xyz,1.0);
}
